INSERT INTO `services` (`title`, `slug`, `label_en`, `icon`, `number`, `excerpt`, `items`, `is_featured`, `is_published`, `sort_order`) VALUES
('هویت بصری و برندینگ', 'هویت-بصری-و-برندینگ', 'Brand Identity', '✦', '۰۱', 'هویت بصری، لوگو، سیستم گرافیکی و زبان بصری منسجم برای ساخت یک برند قابل تشخیص.', '["پژوهش و تحلیل رقبا","طراحی لوگو و نشانه","سیستم گرافیکی و تایپوگرافی","راهنمای کاربرد هویت (Brand Book)","اقلام اداری و چاپی"]', 1, 1, 1),
('تولید محتوای خلاق', 'تولید-محتوای-خلاق', 'Creative Content', '◌', '۰۲', 'ایده‌پردازی، عکاسی، ویدئو، طراحی و محتوای شبکه‌های اجتماعی با یک نگاه یکپارچه.', '["تقویم محتوایی","عکاسی محصول و پرتره","تولید ویدئو و ریلز","طراحی پست و استوری","کپیشن‌نویسی و مدیریت انتشار"]', 1, 1, 2),
('دیجیتال مارکتینگ', 'دیجیتال-مارکتینگ', 'Digital Marketing', '↗', '۰۳', 'استراتژی محتوا، شبکه‌های اجتماعی، تبلیغات دیجیتال و بهینه‌سازی برای رشد واقعی.', '["استراتژی دیجیتال","مدیریت کمپین تبلیغاتی","تحلیل و گزارش عملکرد","بهینه‌سازی نرخ تبدیل","مدیریت شبکه‌های اجتماعی"]', 1, 1, 3),
('کمپین تبلیغاتی', 'کمپین-تبلیغاتی', 'Ad Campaign', '⌁', '۰۴', 'از کانسپت و سناریو تا اجرا و انتشار؛ کمپین‌هایی که یک پیام مشخص را به یک تجربه تبدیل می‌کنند.', '["کانسپت و ایده مرکزی","سناریو و استوری‌بورد","اجرا و تولید","انتشار و رسانه‌گذاری","گزارش نتیجه کمپین"]', 1, 1, 4),
('طراحی وب', 'طراحی-وب', 'Web Design', '+', '۰۵', 'طراحی رابط کاربری و تجربه کاربری مدرن، سریع و متناسب با هویت برند شما.', '["طراحی UI/UX","پیاده‌سازی واکنش‌گرا","بهینه‌سازی سرعت","سئوی تکنیکال","پشتیبانی و نگهداری"]', 0, 1, 5),
('استراتژی و مشاوره', 'استراتژی-و-مشاوره', 'Strategy', '◫', '۰۶', 'شناخت مسئله، تعریف مسیر و تبدیل اهداف کسب‌وکار به یک برنامه‌ی اجرایی قابل اندازه‌گیری.', '["جلسات شناخت و پژوهش","تعریف جایگاه برند","نقشه راه ارتباطی","شاخص‌های اندازه‌گیری","مشاوره مستمر"]', 0, 1, 6);
