INSERT INTO `testimonials` (`name`, `role`, `company`, `quote`, `rating`, `sort_order`, `is_published`) VALUES
('مدیر بازاریابی', 'مدیر بازاریابی', 'رنس تکس', 'تیم نگاه مدیا مسئله ما را درست فهمید و هویتی ساخت که واقعاً ما را از رقبا جدا کرد.', 5, 1, 1),
('مدیر گالری', 'مدیر گالری', 'گالری طلاوجواهر محمود', 'کیفیت عکاسی و محتوا فراتر از انتظار ما بود؛ فروش آنلاین‌مان به‌طور محسوسی رشد کرد.', 5, 2, 1),
('مسئول روابط عمومی', 'روابط عمومی', 'دانشگاه شهید چمران اهواز', 'دقت در زمان‌بندی و حرفه‌ای‌گری در اجرا، چیزی بود که در پروژه‌های بزرگ به آن نیاز داشتیم.', 5, 3, 1);
INSERT INTO `faqs` (`question`, `answer`, `group`, `sort_order`, `is_published`) VALUES
('فرآیند شروع همکاری چگونه است؟', 'کافی است فرم تماس را پر کنید یا با ما تماس بگیرید. در اولین جلسه (رایگان) درباره هدف، مخاطب و بودجه صحبت می‌کنیم و پس از آن یک پیشنهاد مکتوب شامل دامنه کار، زمان‌بندی و هزینه ارسال می‌کنیم.', 'general', 1, 1),
('مدت زمان اجرای پروژه‌ها چقدر است؟', 'بسته به دامنه کار متفاوت است؛ یک پروژه هویت بصری معمولاً ۳ تا ۶ هفته و یک کمپین کامل ۴ تا ۸ هفته زمان می‌برد. زمان‌بندی دقیق در پیشنهاد اولیه مشخص می‌شود.', 'general', 2, 1),
('آیا امکان همکاری پروژه‌ای از راه دور وجود دارد؟', 'بله. بخش زیادی از پروژه‌های ما به‌صورت غیرحضوری و با جلسات آنلاین انجام می‌شود. تحویل فایل‌ها و بازخوردها نیز از طریق ابزارهای اشتراک‌گذاری انجام می‌شود.', 'general', 3, 1),
('هزینه پروژه‌ها چگونه محاسبه می‌شود؟', 'هزینه بر اساس دامنه کار، تعداد خروجی‌ها و زمان مورد نیاز محاسبه می‌شود. پیش از شروع، یک برآورد شفاف و تفکیک‌شده ارائه می‌دهیم تا هیچ هزینه پنهانی وجود نداشته باشد.', 'contact', 4, 1),
('آیا پس از تحویل پروژه پشتیبانی می‌کنید؟', 'بله. پس از تحویل، یک دوره پشتیبانی برای اصلاحات جزئی در نظر گرفته می‌شود و برای برندهایی که نیاز به حضور مستمر دارند، بسته‌های پشتیبانی ماهانه داریم.', 'services', 5, 1);
INSERT INTO `pages` (`title`, `slug`, `subtitle`, `body`, `show_in_menu`, `show_in_footer`, `is_published`, `sort_order`) VALUES
('حریم خصوصی', 'حریم-خصوصی', 'نحوه استفاده از اطلاعات شما در نگاه مدیا', '<h2>اطلاعاتی که جمع‌آوری می‌کنیم</h2><p>هنگام ارسال فرم تماس، اطلاعاتی مانند نام، شماره تماس و ایمیل را دریافت می‌کنیم. این اطلاعات فقط برای پیگیری همان درخواست استفاده می‌شود.</p><h2>اطلاعات را با کسی به اشتراک نمی‌گذاریم</h2><p>اطلاعات شما در اختیار اشخاص ثالث قرار نمی‌گیرد و فقط در پایگاه داده این سایت نگهداری می‌شود.</p>', 0, 1, 1, 1),
('شرایط همکاری', 'شرایط-همکاری', 'چارچوب همکاری با آژانس نگاه مدیا', '<h2>دامنه کار</h2><p>پس از توافق، دامنه دقیق کار در قالب یک سند مکتوب مشخص می‌شود و هر تغییر خارج از آن دامنه، با توافق طرفین انجام می‌شود.</p><h2>زمان‌بندی و بازخورد</h2><p>برای حفظ کیفیت و زمان‌بندی، بازخوردها را در بازه‌های مشخص دریافت و اعمال می‌کنیم.</p>', 0, 1, 1, 2);
