('برندینگ', 'برندینگ', 'یادداشت‌هایی درباره ساخت و مدیریت برند', 1),
('تبلیغات', 'تبلیغات', 'درباره کمپین‌ها و رسانه‌گذاری', 2),
('طراحی', 'طراحی', 'درباره طراحی گرافیک و رابط کاربری', 3);
INSERT INTO `posts` (`title`, `slug`, `excerpt`, `body`, `category_id`, `tags`, `is_published`, `published_at`) VALUES
('هویت بصری خوب چه ویژگی‌هایی دارد؟', 'هویت-بصری-خوب-چه-ویژگی‌هایی-دارد', 'یک هویت بصری موفق فقط یک لوگوی زیبا نیست؛ یک سیستم منسجم است که در همه نقاط تماس، یک چیز را می‌گوید.', '<h2>یک سیستم، نه یک لوگو</h2><p>هویت بصری مجموعه‌ای از تصمیم‌هاست: رنگ، تایپوگرافی، شبکه، لحن تصویر و قواعد کاربرد. وقتی این تصمیم‌ها منسجم باشند، برند در هر نقطه تماس قابل تشخیص می‌ماند.</p><h2>سادگی قابل تکرار</h2><p>هویت خوب باید آن‌قدر ساده باشد که در اندازه‌های مختلف و رسانه‌های متفاوت بدون افت کیفیت استفاده شود.</p>', 1, 'برندینگ، هویت بصری، لوگو', 1, NOW()),
('چرا کمپین‌های تبلیغاتی شکست می‌خورند؟', 'چرا-کمپین‌های-تبلیغاتی-شکست-می‌خورند', 'بیشتر کمپین‌ها نه به‌خاطر اجرای ضعیف، بلکه به‌خاطر نبود یک پیام روشن و یک مخاطب مشخص شکست می‌خورند.', '<h2>پیام روشن، پیش از هر چیز</h2><p>اگر نتوانید پیام کمپین را در یک جمله بگویید، احتمالاً مخاطب هم آن را نخواهد فهمید.</p><h2>مخاطب مشخص</h2><p>«همه» مخاطب نیست. هرچه مخاطب دقیق‌تر تعریف شود، هزینه رسانه‌گذاری بهینه‌تر می‌شود.</p>', 2, 'تبلیغات، کمپین، استراتژی', 1, NOW()),
('طراحی وب برای برندهای ایرانی: ۵ نکته کاربردی', 'طراحی-وب-برای-برندهای-ایرانی', 'از انتخاب فونت فارسی تا چیدمان راست‌چین؛ نکاتی که کیفیت یک وب‌سایت فارسی را تعیین می‌کنند.', '<h2>تایپوگرافی فارسی</h2><p>انتخاب فونت، فاصله خطوط و سلسله‌مراتب بصری در متن فارسی تفاوت چشمگیری در خوانایی ایجاد می‌کند.</p><h2>سرعت</h2><p>بهینه‌سازی تصاویر و کاهش درخواست‌ها، مهم‌ترین عامل تجربه کاربری در اینترنت ایران است.</p>', 3, 'طراحی وب، UX، تایپوگرافی', 1, NOW());
